import { Component } from '@angular/core';
import { AppState } from 'app/core/app.service';
import { Panel } from 'app/utils/panel';
import { ModalService } from 'app/utils/modals/modal.service';
import { PortLimitsDialogComponent, PortLimitsDialogResult } from './port-limits-dialog/port-limits-dialog.component';
import { AbstractControl } from '@angular/forms';


@Component({
    selector: 'settings-general',
    templateUrl: './settings-general.component.html',
})
export class SettingsGeneralComponent {

    /**
     * @see https://github.com/SpiderLabs/ModSecurity/wiki/Reference-Manual#severity
     * @see https://cloudlinux.atlassian.net/browse/DEF-1824
     */
    public modSecCorrelation = {
        1: 7, // debug level
        2: 6,
        3: 5,
        4: 4, // default for UI filtering
        5: 4,
        6: 3,
        7: 3,
        8: 3,
        9: 3,
        10: 3,
        11: 3,
        12: 2,
        13: 2,
        14: 1,
        15: 0, // emergency level
    };
    readonly docsLink = 'https://docs.imunify360.com/';
    readonly docsLinkGeneral = this.docsLink + 'dashboard/#general';
    readonly docsLinkPam = this.docsLink + 'dashboard/#pam';
    readonly docsLinkSmtpTraffic = this.docsLink + 'dashboard/#smtp-traffic-manager';
    readonly docsLinkStandAlone = this.docsLink +
        'installation/#imunify360-stand-alone-non-panel-generic-panel-integration';

    constructor(
        public appState: AppState,
        public panel: Panel,
        private modalService: ModalService,
    ) {}

    async openPortLimitsDialog(
        portLimitsControl: AbstractControl | null,
        configGroup: 'DOS' | 'ENHANCED_DOS',
    ): Promise<void> {
        if (!portLimitsControl) return;

        const currentValue = portLimitsControl.value || {};

        const result = await this.modalService.open<PortLimitsDialogResult, any>(
            PortLimitsDialogComponent,
            {
                data: {
                    portLimits: currentValue,
                    configGroup,
                    formControl: portLimitsControl,
                },
                width: '500px',
            }
        );

        if (result && result.portLimits !== undefined) {
            portLimitsControl.setValue(result.portLimits);
            portLimitsControl.markAsPristine();
        }
    }
}
